ALTER TABLE IF EXISTS public.query_stats SET SCHEMA collect;
ALTER TABLE IF EXISTS public.query_snapshots SET SCHEMA collect;
ALTER TABLE IF EXISTS public.query_store_stats SET SCHEMA collect;
ALTER TABLE IF EXISTS public.deadlocks SET SCHEMA collect;
ALTER TABLE IF EXISTS public.blocked_process_reports SET SCHEMA collect;
ALTER TABLE IF EXISTS public.long_query_completions SET SCHEMA collect;
ALTER TABLE IF EXISTS public.system_health_events SET SCHEMA collect;
