-- ===BATCH=== V14 refresh-passthrough-views
/* V14: refresh every v_* passthrough view's pinned SELECT * column list (#1262).
   Postgres freezes SELECT * at CREATE, so an upgraded store's views omit columns
   ADDed later (V7 plan columns, V9 inventory); CREATE OR REPLACE re-expands them.
   Append-only ADD COLUMNs => the refresh only adds columns at the end (always legal). */

CREATE OR REPLACE VIEW v_wait_stats AS SELECT * FROM wait_stats;
